#!/usr/bin/env bash
set -euo pipefail

# Build/verification imports must not write generated bytecode into source.
export PYTHONDONTWRITEBYTECODE=1
export GOENV=off
export GOFLAGS=
target=${1:-linux_amd64}
case "$target" in linux_amd64) arch=amd64;; linux_arm64) arch=arm64;; *) echo "target must be linux_amd64 or linux_arm64" >&2; exit 2;; esac
build_dir=$(cd "$(dirname "$0")" && pwd)
repo=$(cd "$build_dir/../../.." && pwd)
root="$repo/code"
inputs="$build_dir/inputs.json"
manifest="$build_dir/public-source-v1.json"
output_root=${REPLICARO_UNSIGNED_OUT:-$build_dir/out/$target}
[[ "$output_root" == /* ]] || output_root="$PWD/$output_root"
[[ ! -e "$output_root" && ! -L "$output_root" ]] || { echo "refusing to reuse unsigned output root: $output_root" >&2; exit 2; }
build_root="$output_root/work"
release_root="$output_root/release"
[[ "${REPLICARO_SIGNED_BUILD:-0}" == 0 ]] || { echo "This public builder only creates unsigned outputs." >&2; exit 2; }
(cd "$root/backend" && go run -mod=readonly ./tools/targetverify --target "$target")
bash "$build_dir/verify-toolchains.sh" "$target"
source_identity=$(cd "$build_dir" && go run ./cmd/contract source --root "$repo" --manifest "$manifest")
version=$(cd "$build_dir" && go run ./cmd/contract inputs --file "$inputs" --field version)
build_timestamp=${REPLICARO_BUILD_TIMESTAMP:-}
source_date_epoch=$(cd "$build_dir" && go run ./cmd/contract timestamp --value "$build_timestamp")
[[ "$(node -p 'require(process.argv[1]).version' "$root/frontend/package.json")" == "$version" ]] || { echo "frontend version differs from unsigned build inputs" >&2; exit 2; }
(cd "$root/backend" && go run ./tools/webuiembed -preflight-root "$build_root" -frontend-output "$build_root/frontend/dist")
mkdir -p "$build_root" "$release_root"
# shellcheck source=code/build/unsigned/compile-linux.sh
source "$build_dir/compile-linux.sh" helper
# shellcheck source=code/build/unsigned/compile-linux.sh
source "$build_dir/compile-linux.sh" application
executable_sha256=$(sha256sum "$build_root/replicaro-$target" | cut -d ' ' -f 1)
[[ "$executable_sha256" =~ ^[0-9a-f]{64}$ ]] || { echo "could not hash the built Replicaro executable" >&2; exit 2; }
bundle="$build_root/replicaro-$target-bundle"
rm -rf "$bundle"; mkdir -p "$bundle/share/applications" "$bundle/share/icons/hicolor/256x256/apps" "$bundle/share/systemd/user" "$build_root/provenance"
cp "$build_root/replicaro-$target" "$bundle/replicaro"
cp "$build_dir/install-linux.sh" "$bundle/install.sh"
cp "$build_dir/uninstall-linux.sh" "$bundle/uninstall.sh"
cp "$root/backend/engines/metadata.json" "$build_root/provenance/engines-metadata.json"
cp "$root/backend/rclone/assets/metadata.json" "$build_root/provenance/rclone-metadata.json"
cp "$root/backend/integrations/catalog.json" "$build_root/provenance/integrations-catalog.json"
cp "$build_dir/appimagetool-metadata.json" "$build_root/provenance/"
python3 "$build_dir/write-licenses.py" --platform linux --output "$bundle/LICENSES.txt"
cp "$root/backend/desktop/assets/packaging/replicaro-mark-teal-256.png" "$bundle/share/icons/hicolor/256x256/apps/replicaro.png"
cat > "$bundle/share/applications/replicaro.desktop" <<DESKTOP
[Desktop Entry]
Type=Application
Name=Replicaro
Exec="@REPLICARO_EXECUTABLE@"
Terminal=false
Categories=Utility;Archiving;
Icon=replicaro
DESKTOP
cat > "$bundle/share/systemd/user/replicaro.service" <<SERVICE
# Managed by Replicaro
[Unit]
Description=Replicaro backup companion
After=network-online.target
[Service]
Type=simple
ExecStart="@REPLICARO_EXECUTABLE@"
Restart=on-failure
[Install]
WantedBy=default.target
SERVICE
printf '{"schema":"replicaro-product-provenance-v2","target":"%s","version":"%s","buildTimestamp":"%s","source":"https://github.com/replicaro/replicaro","sourceIdentity":"%s","executableSha256":"sha256:%s","signed":false}\n' "$target" "$version" "$build_timestamp" "$source_identity" "$executable_sha256" > "$build_root/provenance/product-provenance.json"
printf '{"target":"%s","version":"%s","buildTimestamp":"%s","staticLinuxBinary":true,"storageHelper":"embedded","storageHelperTarget":"%s","formats":["tar.gz","deb","rpm","AppImage"],"publicFormats":["deb","rpm","AppImage","tar.gz"],"frontend":"embedded","backend":"replicaro","licenses":"LICENSES.txt"}\n' "$target" "$version" "$build_timestamp" "$target" > "$build_root/provenance/manifest.json"
bash "$build_dir/sbom.sh" "$target" "$build_root/provenance/sbom.cdx.json"
chmod 700 "$bundle/replicaro" "$bundle/install.sh" "$bundle/uninstall.sh"
tar --sort=name --mtime="@$source_date_epoch" --owner=0 --group=0 --numeric-owner -C "$build_root" -cf - "$(basename "$bundle")" | gzip -n -9 > "$build_root/replicaro-$version-$target.tar.gz"
SOURCE_DATE_EPOCH="$source_date_epoch" REPLICARO_TARGET_OUT="$build_root" bash "$build_dir/package-linux-formats.sh" "$target"
for artifact in \
  "$build_root/Replicaro-$version-$target.AppImage" \
  "$build_root/replicaro-$version-$target.deb" \
  "$build_root/replicaro-$version-$target.rpm" \
  "$build_root/replicaro-$version-$target.tar.gz"; do
  cp "$artifact" "$release_root/"
done
(cd "$build_dir" && go run ./cmd/contract write --root "$release_root" --inputs "$inputs" --target "$target" --source-identity "$source_identity" --build-timestamp "$build_timestamp")
printf 'Unsigned %s outputs created in %s\n' "$target" "$release_root"
